public record Point(int x, int y) {}
Point p = new Point(3, 5);
System.out.println(p.x());
System.out.println(p);

public record User(String name, int age) {
    public User {
        if (age < 0) throw new IllegalArgumentException("negative age");
        name = name.strip();
    }
}
User u = new User("  Alice  ", 25);

sealed interface Shape permits Circle, Square {}
record Circle(double r) implements Shape {}
record Square(double s) implements Shape {}

double area = switch (shape) {
    case Circle c -> Math.PI * c.r() * c.r();
    case Square s -> s.s() * s.s();
};

Object obj = "Hello World";
String desc = switch (obj) {
    case String s -> "any string: " + s;
    case String s when s.length() > 5 -> "long string: " + s;
    default -> "other";
};

System.out.println("A: before submit");
try (var executor = Executors.newVirtualThreadPerTaskExecutor()) {
    executor.submit(() -> {
        Thread.sleep(10);
        System.out.println("B: in virtual thread");
    });
    System.out.println("C: after submit");
}

ExecutorService pool = Executors.newFixedThreadPool(10); // Virtual threads in a pool?
try (var executor = pool) {
    for (int i = 0; i < 100_000; i++) {
        executor.submit(() -> doWork());
    }
}

char grade = 'B';
int score = switch (grade) {
    case 'A' -> 100;
    case 'B' -> 80;
    case 'C', 'D' -> 60;
    default -> {
        System.out.println("Failing");
        yield 0;
    }
};
System.out.println(score);

class Counter {
    private int count = 0;
    public synchronized void increment() {
        // Simulates blocking I/O
        fetchData();
        count++;
    }
}
// Called from virtual threads
